1	export type Item = { type: string };
2	export type Step = { op: string; items?: Item[] };
3	export type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };
4	
5	export type StepResult = { premium: number };
6	export type ScenarioResult = { results: StepResult[] };
7	
8	const BASE_PREMIUMS: Record<string, number> = {
9	  sword: 100,
10	  amulet: 60,
11	  staff: 80,
12	  potion: 40,
13	};
14	
15	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
16	const PROCESSING_FEE = 5;
17	
18	const policyBasePremium = (items: Item[]): number =>
19	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
20	
21	const quotePremium = (items: Item[]): number => {
22	  const basePremium = policyBasePremium(items);
23	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
24	  return basePremium + firstInsuranceSurcharge + PROCESSING_FEE;
25	};
26	
27	export const runScenario = (scenario: Scenario): ScenarioResult => ({
28	  results: scenario.steps.map((step) => ({
29	    premium: quotePremium(step.items ?? []),
30	  })),
31	});
